#include <stdio.h>
#include <openssl/bn.h>

#define NBITS 256

void printBN(char *msg, BIGNUM * a){

	char * number_str = BN_bn2hex(a);
	printf("%s %s\n", msg, number_str);
	OPENSSL_free(number_str);
}

int main(){

	BN_CTX *ctx = BN_CTX_new();
	BIGNUM *n = BN_new();
	BIGNUM *e = BN_new();
	BIGNUM *s = BN_new();
	BIGNUM *m = BN_new();
	BN_hex2bn(&s, "45c12019e2ec23b51760f8b7cd466aea7b5cca737fa6c62e894c33b407387c6e");
	BN_hex2bn(&e, "10001");
	BN_hex2bn(&n, "");

	BN_mod_exp(m, s, e, n, ctx);

	printBN("(*) Verify Sign = ", m);
}